<?php require 'header.php';$product=(int)$pdo->query('SELECT COUNT(*) FROM products WHERE is_active=1')->fetchColumn();$physical=(float)$pdo->query('SELECT COALESCE(SUM(qty_on_hand),0) FROM stock_balances')->fetchColumn();$reserved=(float)$pdo->query('SELECT COALESCE(SUM(qty_reserved),0) FROM stock_balances')->fetchColumn();$transit=(int)$pdo->query("SELECT COUNT(*) FROM inbound_shipments WHERE status='IN_TRANSIT'")->fetchColumn();$low=$pdo->query("SELECT p.sku,p.product_name,p.minimum_stock,COALESCE(SUM(s.qty_on_hand-s.qty_reserved),0) available,p.unit FROM products p LEFT JOIN stock_balances s ON s.product_id=p.product_id WHERE p.is_active=1 GROUP BY p.product_id HAVING available<=p.minimum_stock ORDER BY available LIMIT 6")->fetchAll();?><div class="page-intro"><div><h2>Ringkasan operasional</h2><p>Informasi stok dan aktivitas gudang hari ini.</p></div><span class="date-badge">● Sistem aktif</span></div><div class="stats"><article class="stat blue"><div><span>Barang aktif</span><b><?=e($product)?></b><small>Jenis material dan produk</small></div><i>▣</i></article><article class="stat green"><div><span>Stok fisik</span><b><?=number_format($physical,0,',','.')?></b><small>Total unit di gudang</small></div><i>▥</i></article><article class="stat orange"><div><span>Stok dialokasikan</span><b><?=number_format($reserved,0,',','.')?></b><small>Untuk pesanan berjalan</small></div><i>◈</i></article><article class="stat purple"><div><span>Dalam perjalanan</span><b><?=e($transit)?></b><small>Pengiriman dari supplier</small></div><i>↗</i></article></div><section class="panel"><div class="panel-head"><div><h3>Perhatian stok minimum</h3><p>Barang yang perlu diperiksa atau dilakukan pembelian ulang.</p></div><a class="text-link" href="reports.php">Lihat laporan →</a></div><div class="table-wrap"><table><thead><tr><th>SKU</th><th>Nama barang</th><th>Stok tersedia</th><th>Minimum</th><th>Status</th></tr></thead><tbody><?php foreach($low as $r):?><tr><td><code><?=e($r['sku'])?></code></td><td><b><?=e($r['product_name'])?></b></td><td><?=e($r['available'].' '.$r['unit'])?></td><td><?=e($r['minimum_stock'].' '.$r['unit'])?></td><td><span class="badge danger">Perlu reorder</span></td></tr><?php endforeach;if(!$low):?><tr><td colspan="5" class="empty">✓ Tidak ada barang yang berada di bawah stok minimum.</td></tr><?php endif?></tbody></table></div></section><?php require 'footer.php';?>